import React from 'react';
import Gradient from 'ink-gradient';
import BigText from 'ink-big-text';
import { useCounter } from '../hooks/useCounter.js';
const titleText = 'Tevm Create';
const loadingTitleText = 'Tevm Creating...';
export const FancyCreateTitle = ({ loading }) => {
    const { count: i } = useCounter(titleText.length);
    const text = `${loading ? loadingTitleText : titleText}${loading ? '.'.repeat(Math.floor(i * 0.15) % 4) : ''}`.slice(0, i + 1);
    const G = Gradient;
    const BT = BigText;
    return (React.createElement(G, { name: "pastel" },
        React.createElement(BT, { font: "tiny", text: text })));
};
